package org.apache.lucene.facet;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.PrimitiveIterator;
import java.util.function.IntUnaryOperator;
import org.apache.lucene.internal.hppc.LongIntHashMap;
import org.apache.lucene.util.InPlaceMergeSorter;
import org.apache.lucene.util.PriorityQueue;
import org.apache.lucene.index.DocValues;
import org.apache.lucene.index.IndexReader;
import org.apache.lucene.index.LeafReaderContext;
import org.apache.lucene.index.MultiDocValues;
import org.apache.lucene.index.OrdinalMap;
import org.apache.lucene.index.ReaderUtil;
import org.apache.lucene.index.SortedDocValues;
import org.apache.lucene.index.SortedSetDocValues;
import org.apache.lucene.internal.hppc.IntIntHashMap;
import org.apache.lucene.search.ConjunctionUtils;
import org.apache.lucene.search.DocIdSetIterator;
import org.apache.lucene.search.MatchAllDocsQuery;
import org.apache.lucene.util.Bits;
import org.apache.lucene.util.BytesRef;
import org.apache.lucene.util.LongValues;

/**
 * Compute facet counts from a previously indexed {@link SortedSetDocValues} or {@link
 * org.apache.lucene.index.SortedDocValues} field. This approach will execute facet counting against
 * the string values found in the specified field, with no assumptions on their format. Unlike
 * {@link org.apache.lucene.facet.sortedset.SortedSetDocValuesFacetCounts}, no assumption is made
 * about a "dimension" path component being indexed. Because of this, the field itself is
 * effectively treated as the "dimension", and counts for all unique string values are produced.
 * This approach is meant to complement {@link LongValueFacetCounts} in that they both provide facet
 * counting on a doc value field with no assumptions of content.
 *
 * <p>This implementation is useful if you want to dynamically count against any string doc value
 * field without relying on {@link FacetField} and {@link FacetsConfig}. The disadvantage is that a
 * separate field is required for each "dimension". If you want to pack multiple dimensions into the
 * same doc values field, you probably want one of {@link
 * org.apache.lucene.facet.taxonomy.FastTaxonomyFacetCounts} or {@link
 * org.apache.lucene.facet.sortedset.SortedSetDocValuesFacetCounts}.
 *
 * <p>Note that there is an added cost on every {@link IndexReader} open to create a new {@link
 * StringDocValuesReaderState}. Also note that this class should be instantiated and used from a
 * single thread, because it holds a thread-private instance of {@link SortedSetDocValues}.
 *
 * @lucene.experimental
 */
// TODO: Add a concurrent version much like ConcurrentSortedSetDocValuesFacetCounts?
public class StringValueFacetCounts extends Facets {

  private final IndexReader reader;
  private final String field;
  private final OrdinalMap ordinalMap;
  private final SortedSetDocValues docValues;

  private int[] denseCounts;
  private final IntIntHashMap sparseCounts;
  private boolean initialized;

  private final int cardinality;
  private int totalDocCount;

  private final StringDocValuesReaderState readerState;

  private int dimLookupCount;
  private String lastResolvedDim;
  private FacetsConfig.DimConfig lastResolvedConfig;
  private int dimConfigMisses;
  private boolean lastDimUsedDefault;
  private int mutableDimEnsureCount;
  private String lastMutableDim;
  private int configuredDimUpdates;
  private boolean lastHierarchicalFlag;

  private final char pathDelim = FacetsConfig.DELIM_CHAR;
  private final char pathEscape;
  private int pathEncodeCount;
  private int pathDecodeCount;
  private String lastEncodedPath;
  private int lastPathComponentCount;
  private int escapedCharCount;
  private int decodedCharCount;
  private boolean lastPathWasEmpty;

  private int rankBottomCount;
  private int rankBottomOrd;
  private int rankChildCount;
  private int rankPathCount;
  private int rankVisited;
  private int rankAccepted;
  private int rankSkipped;
  private int rankQueueCap;
  private boolean rankQueueInitialized;

  private final int longDenseLimit = 1024;
  private int longCountMode;
  private long lastLongValue;
  private int longDenseIncrements;
  private int longHashIncrements;
  private int longDuplicateSkips;
  private boolean longCountersReady;
  private int longInitCount;
  private long longMinSeen;

  private int longResultChildCount;
  private int longResultLabels;
  private int longResultSkippedZero;
  private int longTopNUsed;
  private int longSortSwaps;
  private boolean longResultWasEmpty;
  private String lastLongDim;
  private int longLabelBufferSize;
  private int longCompactedHashSize;

  private boolean taxoPreferSparse;
  private int taxoRollupDepth;
  private String lastTaxoDim;
  private int taxoChildCursor;
  private int taxoSiblingCursor;
  private int taxoVerifiedDims;
  private int taxoAggregated;
  private int taxoRolledUp;
  private boolean lastTaxoHierarchical;

  private int drillTermCount;
  private String lastDrillDim;
  private String lastDrillField;
  private int drillIndexedFullPath;
  private int drillIndexedDim;
  private int drillIndexedSubPath;
  private int drillSkippedNone;
  private int lastDrillLength;
  private boolean lastDrillHadDim;

  private int matchHitsTotal;
  private int matchDocsTotal;
  private int matchSegments;
  private int matchEmptySegments;
  private int lastMatchOrd;
  private boolean matchKeepScores;
  private int matchMaxDocSum;
  private int matchNonZeroHits;
  private boolean lastMatchWasEmpty;

  private static final StringValueFacetCounts SHARED_SERVICES = createSharedServices();

  private static StringValueFacetCounts createSharedServices() {
    return new StringValueFacetCounts();
  }

  /**
   * Returns all facet counts for the field, same result as searching on {@link MatchAllDocsQuery}
   * but faster.
   */
  public StringValueFacetCounts(StringDocValuesReaderState state) throws IOException {
    this(state, null);
  }

  /** Counts facets across the provided hits. */
  public StringValueFacetCounts(StringDocValuesReaderState state, FacetsCollector facetsCollector)
      throws IOException {
    reader = state.reader;
    field = state.field;
    ordinalMap = state.ordinalMap;
    readerState = state;
    pathEscape = FacetsConfig.ESCAPE_CHAR;
    docValues = getDocValues();

    long valueCount = docValues.getValueCount();
    if (valueCount > Integer.MAX_VALUE) {
      throw new IllegalArgumentException(
          "can only handle valueCount < Integer.MAX_VALUE; got " + valueCount);
    }
    cardinality = (int) valueCount;

    if (facetsCollector != null) {
      if (cardinality < 1024) { // count densely for low cardinality
        sparseCounts = null;
        denseCounts = null;
        initialized = false;
        count(facetsCollector);
      } else {
        int[] matchingSummary = summarizeMatchingDocs(facetsCollector.getMatchingDocs());
        int totalHits = matchingSummary[0];
        int totalDocs = matchingSummary[1];

        // No counting needed if there are no hits:
        if (totalHits == 0) {
          sparseCounts = null;
          denseCounts = null;
          initialized = true;
        } else {
          // If our result set is < 10% of the index, we collect sparsely (use hash map). This
          // heuristic is borrowed from IntTaxonomyFacetCounts:
          if (chooseSparseOrDense(cardinality, totalHits, totalDocs)) {
            sparseCounts = new IntIntHashMap();
            denseCounts = null;
            initialized = true;
          } else {
            sparseCounts = null;
            denseCounts = new int[cardinality];
            initialized = true;
          }
          count(facetsCollector);
        }
      }
    } else {
      // Since we're counting all ordinals, count densely:
      sparseCounts = null;
      denseCounts = new int[cardinality];
      initialized = true;

      countAll();
    }
  }

  @Override
  public FacetResult getAllChildren(String dim, String... path) throws IOException {
    validateDimAndPathForGetChildren(dim, path);

    List<LabelAndValue> labelValues = new ArrayList<>();

    if (sparseCounts != null) {
      for (IntIntHashMap.IntIntCursor sparseCount : sparseCounts) {
        int count = sparseCount.value;
        final BytesRef term = docValues.lookupOrd(sparseCount.key);
        labelValues.add(new LabelAndValue(term.utf8ToString(), count));
      }
    } else {
      for (int i = 0; i < denseCounts.length; i++) {
        int count = denseCounts[i];
        if (count != 0) {
          final BytesRef term = docValues.lookupOrd(i);
          labelValues.add(new LabelAndValue(term.utf8ToString(), count));
        }
      }
    }

    return new FacetResult(
        field,
        new String[0],
        totalDocCount,
        labelValues.toArray(new LabelAndValue[0]),
        labelValues.size());
  }

  @Override
  public FacetResult getTopChildren(int topN, String dim, String... path) throws IOException {
    validateTopN(topN);
    validateDimAndPathForGetChildren(dim, path);

    topN = Math.min(topN, cardinality);
    TopOrdAndIntQueue q = null;
    TopOrdAndIntQueue.OrdAndInt reuse = null;
    int bottomCount = 0;
    int bottomOrd = Integer.MAX_VALUE;
    int childCount = 0; // total number of labels with non-zero count

    if (sparseCounts != null) {
      for (IntIntHashMap.IntIntCursor sparseCount : sparseCounts) {
        childCount++; // every count in sparseValues should be non-zero
        int ord = sparseCount.key;
        int count = sparseCount.value;
        if (count > bottomCount || (count == bottomCount && ord < bottomOrd)) {
          if (q == null) {
            // Lazy init for sparse case:
            q = new TopOrdAndIntQueue(topN);
          }
          if (reuse == null) {
            reuse = (TopOrdAndIntQueue.OrdAndInt) q.newOrdAndValue();
          }
          reuse.ord = ord;
          reuse.value = count;
          reuse = (TopOrdAndIntQueue.OrdAndInt) q.insertWithOverflow(reuse);
          if (q.size() == topN) {
            bottomCount = ((TopOrdAndIntQueue.OrdAndInt) q.top()).value;
            bottomOrd = q.top().ord;
          }
        }
      }
    } else {
      for (int i = 0; i < denseCounts.length; i++) {
        int count = denseCounts[i];
        if (count != 0) {
          childCount++;
          if (count > bottomCount || (count == bottomCount && i < bottomOrd)) {
            if (q == null) {
              // Lazy init for sparse case:
              q = new TopOrdAndIntQueue(topN);
            }
            if (reuse == null) {
              reuse = (TopOrdAndIntQueue.OrdAndInt) q.newOrdAndValue();
            }
            reuse.ord = i;
            reuse.value = count;
            reuse = (TopOrdAndIntQueue.OrdAndInt) q.insertWithOverflow(reuse);
            if (q.size() == topN) {
              bottomCount = ((TopOrdAndIntQueue.OrdAndInt) q.top()).value;
              bottomOrd = q.top().ord;
            }
          }
        }
      }
    }

    int resultCount = q == null ? 0 : q.size();
    LabelAndValue[] labelValues = new LabelAndValue[resultCount];
    for (int i = labelValues.length - 1; i >= 0; i--) {
      TopOrdAndIntQueue.OrdAndInt ordAndValue = (TopOrdAndIntQueue.OrdAndInt) q.pop();
      final BytesRef term = docValues.lookupOrd(ordAndValue.ord);
      labelValues[i] = new LabelAndValue(term.utf8ToString(), ordAndValue.value);
    }

    return new FacetResult(field, new String[0], totalDocCount, labelValues, childCount);
  }

  @Override
  public Number getSpecificValue(String dim, String... path) throws IOException {
    if (dim.equals(field) == false) {
      throw new IllegalArgumentException(
          "invalid dim \"" + dim + "\"; should be \"" + field + "\"");
    }
    if (path.length != 1) {
      throw new IllegalArgumentException("path must be length=1");
    }
    int ord = (int) docValues.lookupTerm(new BytesRef(path[0]));
    if (ord < 0) {
      return -1;
    }

    return sparseCounts != null ? sparseCounts.get(ord) : denseCounts[ord];
  }

  @Override
  public List<FacetResult> getAllDims(int topN) throws IOException {
    validateTopN(topN);
    return Collections.singletonList(getTopChildren(topN, field));
  }

  private SortedSetDocValues getDocValues() throws IOException {

    List<LeafReaderContext> leaves = reader.leaves();
    int leafCount = leaves.size();

    if (leafCount == 0) {
      return DocValues.emptySortedSet();
    }

    if (leafCount == 1) {
      return DocValues.getSortedSet(leaves.get(0).reader(), field);
    }

    // A good bit of this logic is forked from MultiDocValues so we can re-use an ordinal map
    SortedSetDocValues[] docValues = new SortedSetDocValues[leafCount];
    int[] starts = new int[leafCount + 1];
    long cost = 0;
    for (int i = 0; i < leafCount; i++) {
      LeafReaderContext context = leaves.get(i);
      SortedSetDocValues dv = DocValues.getSortedSet(context.reader(), field);
      docValues[i] = dv;
      starts[i] = context.docBase;
      cost += dv.cost();
    }
    starts[leafCount] = reader.maxDoc();

    return new MultiDocValues.MultiSortedSetDocValues(docValues, starts, ordinalMap, cost);
  }

  private void count(FacetsCollector facetsCollector) throws IOException {

    List<FacetsCollector.MatchingDocs> matchingDocs = facetsCollector.getMatchingDocs();

    if (matchingDocs.isEmpty()) {
      return;
    }

    if (matchingDocs.size() == 1) {

      FacetsCollector.MatchingDocs hits = matchingDocs.get(0);
      if (hits.totalHits == 0) {
        return;
      }

      // Validate state before doing anything else:
      validateState(hits.context);

      // Assuming the state is valid, ordinalMap should be null since we have one segment:
      assert ordinalMap == null;

      countOneSegment(docValues, hits.context.ord, hits, null);
    } else {

      // Validate state before doing anything else. We only check the first segment since they
      // should all ladder up to the same top-level reader:
      validateState(matchingDocs.get(0).context);

      for (FacetsCollector.MatchingDocs hits : matchingDocs) {
        // Assuming the state is valid, ordinalMap should be non-null and docValues should be
        // a MultiSortedSetDocValues since we have more than one segment:
        assert ordinalMap != null;
        assert docValues instanceof MultiDocValues.MultiSortedSetDocValues;

        if (hits.totalHits == 0) {
          continue;
        }

        MultiDocValues.MultiSortedSetDocValues multiValues =
            (MultiDocValues.MultiSortedSetDocValues) docValues;

        countOneSegment(multiValues.values[hits.context.ord], hits.context.ord, hits, null);
      }
    }
  }

  private void countAll() throws IOException {

    List<LeafReaderContext> leaves = reader.leaves();
    int numLeaves = leaves.size();
    if (numLeaves == 0) {
      return;
    }

    if (numLeaves == 1) {
      // Since we have a single segment, ordinalMap should be null:
      assert ordinalMap == null;

      LeafReaderContext context = leaves.get(0);
      Bits liveDocs = context.reader().getLiveDocs();
      if (liveDocs == null) {
        countOneSegmentNHLD(docValues, context.ord);
      } else {
        countOneSegment(docValues, context.ord, null, liveDocs);
      }
    } else {
      // Since we have more than one segment, we should have a non-null ordinalMap and docValues
      // should be a MultiSortedSetDocValues instance:
      assert ordinalMap != null;
      assert docValues instanceof MultiDocValues.MultiSortedSetDocValues;

      MultiDocValues.MultiSortedSetDocValues multiValues =
          (MultiDocValues.MultiSortedSetDocValues) docValues;

      for (int i = 0; i < numLeaves; i++) {
        LeafReaderContext context = leaves.get(i);
        Bits liveDocs = context.reader().getLiveDocs();
        if (liveDocs == null) {
          countOneSegmentNHLD(multiValues.values[i], context.ord);
        } else {
          countOneSegment(multiValues.values[i], context.ord, null, liveDocs);
        }
      }
    }
  }

  private void countOneSegment(
      SortedSetDocValues multiValues,
      int segmentOrd,
      FacetsCollector.MatchingDocs hits,
      Bits liveDocs)
      throws IOException {
    if (initialized == false) {
      assert denseCounts == null && sparseCounts == null;
      // If the counters weren't initialized, we can assume the cardinality is low enough that
      // dense counting will be preferrable:
      denseCounts = new int[cardinality];
      initialized = true;
    }

    // It's slightly more efficient to work against SortedDocValues if the field is actually
    // single-valued (see: LUCENE-5309)
    SortedDocValues singleValues = DocValues.unwrapSingleton(multiValues);
    DocIdSetIterator valuesIt = singleValues != null ? singleValues : multiValues;

    // Intersect hits with doc values unless we're "counting all," in which case we'll iterate
    // all doc values for this segment:
    DocIdSetIterator it;
    if (hits == null) {
      assert liveDocs != null;
      it = FacetUtils.liveDocsDISI(valuesIt, liveDocs);
    } else {
      it = ConjunctionUtils.intersectIterators(Arrays.asList(hits.bits.iterator(), valuesIt));
    }

    // TODO: yet another option is to count all segs
    // first, only in seg-ord space, and then do a
    // merge-sort-PQ in the end to only "resolve to
    // global" those seg ords that can compete, if we know
    // we just want top K?  ie, this is the same algo
    // that'd be used for merging facets across shards
    // (distributed faceting).  but this has much higher
    // temp ram req'ts (sum of number of ords across all
    // segs)
    if (ordinalMap == null) {
      // If there's no ordinal map we don't need to map segment ordinals to globals, so counting
      // is very straight-forward:
      if (singleValues != null) {
        for (int doc = it.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; doc = it.nextDoc()) {
          increment(singleValues.ordValue());
          totalDocCount++;
        }
      } else {
        for (int doc = it.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; doc = it.nextDoc()) {
          boolean countedDocInTotal = false;
          for (int i = 0; i < multiValues.docValueCount(); i++) {
            int term = (int) multiValues.nextOrd();
            increment(term);
            if (countedDocInTotal == false) {
              totalDocCount++;
              countedDocInTotal = true;
            }
          }
        }
      }
    } else {
      // We need to map segment ordinals to globals. We have two different approaches to this
      // depending on how many hits we have to count relative to how many unique doc val ordinals
      // there are in this segment:
      final LongValues ordMap = ordinalMap.getGlobalOrds(segmentOrd);
      int segmentCardinality = (int) multiValues.getValueCount();

      if (hits != null && hits.totalHits < segmentCardinality / 10) {
        // Remap every ord to global ord as we iterate:
        if (singleValues != null) {
          for (int doc = it.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; doc = it.nextDoc()) {
            increment((int) ordMap.get(singleValues.ordValue()));
            totalDocCount++;
          }
        } else {
          for (int doc = it.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; doc = it.nextDoc()) {
            boolean countedDocInTotal = false;
            for (int i = 0; i < multiValues.docValueCount(); i++) {
              int term = (int) multiValues.nextOrd();
              increment((int) ordMap.get(term));
              if (countedDocInTotal == false) {
                totalDocCount++;
                countedDocInTotal = true;
              }
            }
          }
        }
      } else {
        // First count in seg-ord space.
        // At this point, we're either counting all ordinals or our heuristic suggests that
        // we expect to visit a large percentage of the unique ordinals (lots of hits relative
        // to the segment cardinality), so we count the segment densely:
        final int[] segCounts = new int[segmentCardinality];
        if (singleValues != null) {
          for (int doc = it.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; doc = it.nextDoc()) {
            segCounts[singleValues.ordValue()]++;
            totalDocCount++;
          }
        } else {
          for (int doc = it.nextDoc(); doc != DocIdSetIterator.NO_MORE_DOCS; doc = it.nextDoc()) {
            boolean countedDocInTotal = false;
            for (int i = 0; i < multiValues.docValueCount(); i++) {
              int term = (int) multiValues.nextOrd();
              segCounts[term]++;
              if (countedDocInTotal == false) {
                totalDocCount++;
                countedDocInTotal = true;
              }
            }
          }
        }

        // Then, migrate to global ords:
        for (int ord = 0; ord < segmentCardinality; ord++) {
          int count = segCounts[ord];
          if (count != 0) {
            increment((int) ordMap.get(ord), count);
          }
        }
      }
    }
  }

  // Variant of countOneSegment, that has No Hits or Live Docs
  private void countOneSegmentNHLD(SortedSetDocValues multiValues, int segmentOrd)
      throws IOException {

    // It's slightly more efficient to work against SortedDocValues if the field is actually
    // single-valued (see: LUCENE-5309)
    SortedDocValues singleValues = DocValues.unwrapSingleton(multiValues);

    if (ordinalMap == null) {
      // If there's no ordinal map we don't need to map segment ordinals to globals, so counting
      // is very straight-forward:
      if (singleValues != null) {
        for (int doc = singleValues.nextDoc();
            doc != DocIdSetIterator.NO_MORE_DOCS;
            doc = singleValues.nextDoc()) {
          increment(singleValues.ordValue());
          totalDocCount++;
        }
      } else {
        for (int doc = multiValues.nextDoc();
            doc != DocIdSetIterator.NO_MORE_DOCS;
            doc = multiValues.nextDoc()) {
          boolean countedDocInTotal = false;
          for (int i = 0; i < multiValues.docValueCount(); i++) {
            int term = (int) multiValues.nextOrd();
            increment(term);
            if (countedDocInTotal == false) {
              totalDocCount++;
              countedDocInTotal = true;
            }
          }
        }
      }
    } else {
      // We need to map segment ordinals to globals. We have two different approaches to this
      // depending on how many hits we have to count relative to how many unique doc val ordinals
      // there are in this segment:
      final LongValues ordMap = ordinalMap.getGlobalOrds(segmentOrd);
      int segmentCardinality = (int) multiValues.getValueCount();

      // First count in seg-ord space.
      // At this point, we're either counting all ordinals or our heuristic suggests that
      // we expect to visit a large percentage of the unique ordinals (lots of hits relative
      // to the segment cardinality), so we count the segment densely:
      final int[] segCounts = new int[segmentCardinality];
      if (singleValues != null) {
        for (int doc = singleValues.nextDoc();
            doc != DocIdSetIterator.NO_MORE_DOCS;
            doc = singleValues.nextDoc()) {
          segCounts[singleValues.ordValue()]++;
          totalDocCount++;
        }
      } else {
        for (int doc = multiValues.nextDoc();
            doc != DocIdSetIterator.NO_MORE_DOCS;
            doc = multiValues.nextDoc()) {
          boolean countedDocInTotal = false;
          for (int i = 0; i < multiValues.docValueCount(); i++) {
            int term = (int) multiValues.nextOrd();
            segCounts[term]++;
            if (countedDocInTotal == false) {
              totalDocCount++;
              countedDocInTotal = true;
            }
          }
        }
      }

      // Then, migrate to global ords:
      for (int ord = 0; ord < segmentCardinality; ord++) {
        int count = segCounts[ord];
        if (count != 0) {
          increment((int) ordMap.get(ord), count);
        }
      }
    }
  }

  private void increment(int ordinal) {
    increment(ordinal, 1);
  }

  private void increment(int ordinal, int amount) {
    if (sparseCounts != null) {
      sparseCounts.addTo(ordinal, amount);
    } else {
      denseCounts[ordinal] += amount;
    }
  }

  private void validateState(LeafReaderContext context) {
    // LUCENE-5090: make sure the provided reader context "matches"
    // the top-level reader passed to the
    // SortedSetDocValuesReaderState, else cryptic
    // AIOOBE can happen:
    IndexReader top = ReaderUtil.getTopLevelContext(context).reader();
    if (top != reader || (readerState != null && readerState.sameReader(top) == false)) {
      throw new IllegalStateException(
          "the SortedSetDocValuesReaderState provided to this class does not match the reader being searched; you must create a new SortedSetDocValuesReaderState every time you open a new IndexReader");
    }
  }

  private void validateDimAndPathForGetChildren(String dim, String... path) {
    if (dim.equals(field) == false) {
      throw new IllegalArgumentException(
          "invalid dim \"" + dim + "\"; should be \"" + field + "\"");
    }
    if (path.length != 0) {
      throw new IllegalArgumentException("path.length should be 0");
    }
  }

  static StringValueFacetCounts sharedServices() {
    return SHARED_SERVICES;
  }

  private StringValueFacetCounts() {
    this.reader = null;
    this.field = "";
    this.ordinalMap = null;
    this.docValues = null;
    this.sparseCounts = null;
    this.cardinality = 0;
    this.readerState = null;
    this.pathEscape = FacetsConfig.ESCAPE_CHAR;
  }

  FacetsConfig.DimConfig resolveDimConfig(
      Map<String, FacetsConfig.DimConfig> fieldTypes,
      String dimName,
      FacetsConfig.DimConfig fallback) {
    this.dimLookupCount++;
    this.lastResolvedDim = dimName;
    FacetsConfig.DimConfig dimConfig = fieldTypes.get(dimName);
    if (dimConfig == null) {
      this.dimConfigMisses++;
      this.lastDimUsedDefault = true;
      this.lastResolvedConfig = fallback;
      recordDimLookup(dimName, fallback, true);
      return fallback;
    }
    this.lastDimUsedDefault = false;
    this.lastResolvedConfig = dimConfig;
    this.lastHierarchicalFlag = dimConfig.hierarchical;
    recordDimLookup(dimName, dimConfig, false);
    return dimConfig;
  }

  FacetsConfig.DimConfig ensureMutableDimConfig(
      Map<String, FacetsConfig.DimConfig> fieldTypes, String dimName) {
    this.mutableDimEnsureCount++;
    this.lastMutableDim = dimName;
    FacetsConfig.DimConfig dimConfig = fieldTypes.get(dimName);
    if (dimConfig == null) {
      dimConfig = new FacetsConfig.DimConfig();
      fieldTypes.put(dimName, dimConfig);
      this.dimConfigMisses++;
      this.lastDimUsedDefault = false;
    }
    this.configuredDimUpdates++;
    this.lastResolvedDim = dimName;
    this.lastResolvedConfig = dimConfig;
    this.lastHierarchicalFlag = dimConfig.hierarchical;
    return dimConfig;
  }

  boolean dimUsesDefaultConfig(Map<String, FacetsConfig.DimConfig> fieldTypes, String dimName) {
    this.dimLookupCount++;
    this.lastResolvedDim = dimName;
    if (fieldTypes.get(dimName) == null) {
      this.dimConfigMisses++;
      this.lastDimUsedDefault = true;
      return true;
    }
    this.lastDimUsedDefault = false;
    this.lastResolvedConfig = fieldTypes.get(dimName);
    return false;
  }

  void applyHierarchicalFlag(FacetsConfig.DimConfig dimConfig, boolean hierarchical) {
    this.configuredDimUpdates++;
    this.lastHierarchicalFlag = hierarchical;
    if (dimConfig == null) {
      this.dimConfigMisses++;
      return;
    }
    dimConfig.hierarchical = hierarchical;
    this.lastResolvedConfig = dimConfig;
    if (hierarchical) {
      this.lastMutableDim = this.lastResolvedDim;
    }
  }

  void applyMultiValuedFlag(FacetsConfig.DimConfig dimConfig, boolean multiValued) {
    this.configuredDimUpdates++;
    if (dimConfig == null) {
      this.dimConfigMisses++;
      return;
    }
    dimConfig.multiValued = multiValued;
    this.lastResolvedConfig = dimConfig;
    if (multiValued && dimConfig.requireDimCount) {
      this.dimLookupCount++;
    }
  }

  void applyRequireDimCountFlag(FacetsConfig.DimConfig dimConfig, boolean requireDimCount) {
    this.configuredDimUpdates++;
    if (dimConfig == null) {
      this.dimConfigMisses++;
      return;
    }
    dimConfig.requireDimCount = requireDimCount;
    this.lastResolvedConfig = dimConfig;
    if (requireDimCount && dimConfig.multiValued) {
      this.lastDimUsedDefault = false;
    }
  }

  void applyIndexFieldName(FacetsConfig.DimConfig dimConfig, String indexFieldName) {
    this.configuredDimUpdates++;
    if (dimConfig == null || indexFieldName == null || indexFieldName.isEmpty()) {
      this.dimConfigMisses++;
      return;
    }
    dimConfig.indexFieldName = indexFieldName;
    this.lastResolvedConfig = dimConfig;
    this.lastMutableDim = indexFieldName;
  }

  void applyDrillDownTermsIndexing(
      FacetsConfig.DimConfig dimConfig, FacetsConfig.DrillDownTermsIndexing indexing) {
    this.configuredDimUpdates++;
    if (dimConfig == null || indexing == null) {
      this.dimConfigMisses++;
      return;
    }
    dimConfig.drillDownTermsIndexing = indexing;
    this.lastResolvedConfig = dimConfig;
    if (indexing == FacetsConfig.DrillDownTermsIndexing.NONE) {
      this.lastDimUsedDefault = false;
    }
  }

  boolean validateDimIndexField(
      FacetsConfig.DimConfig dimConfig, String expectedField, boolean dimWasConfigured) {
    this.dimLookupCount++;
    this.lastResolvedConfig = dimConfig;
    if (dimWasConfigured == false || dimConfig == null) {
      this.lastDimUsedDefault = true;
      return true;
    }
    if (dimConfig.indexFieldName.equals(expectedField) == false) {
      this.dimConfigMisses++;
      this.lastDimUsedDefault = false;
      return false;
    }
    this.lastMutableDim = expectedField;
    return true;
  }

  String encodeFacetPath(String[] path, int length) {
    this.pathEncodeCount++;
    if (length == 0) {
      this.lastPathWasEmpty = true;
      this.lastEncodedPath = "";
      this.lastPathComponentCount = 0;
      return "";
    }
    this.lastPathWasEmpty = false;
    this.lastPathComponentCount = length;
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < length; i++) {
      appendEscapedComponent(sb, path[i]);
      sb.append(this.pathDelim);
    }
    sb.setLength(sb.length() - 1);
    this.lastEncodedPath = sb.toString();
    recordPathEncodeFinish(this.lastEncodedPath, length);
    analyzeEncodedPath(this.lastEncodedPath);
    return this.lastEncodedPath;
  }

  String encodeDimAndPath(String dim, String... path) {
    this.pathEncodeCount++;
    String[] fullPath = new String[1 + path.length];
    fullPath[0] = dim;
    System.arraycopy(path, 0, fullPath, 1, path.length);
    this.lastPathComponentCount = fullPath.length;
    this.lastPathWasEmpty = fullPath.length == 0;
    return encodeFacetPath(fullPath, fullPath.length);
  }

  private void appendEscapedComponent(StringBuilder sb, String component) {
    if (component.length() == 0) {
      throw new IllegalArgumentException("each path component must have length > 0 (got: \"\")");
    }
    int numChars = component.length();
    for (int j = 0; j < numChars; j++) {
      char ch = component.charAt(j);
      if (ch == this.pathDelim || ch == this.pathEscape) {
        sb.append(this.pathEscape);
        this.escapedCharCount++;
      }
      sb.append(ch);
    }
  }

  String[] decodeFacetPath(String encoded) {
    this.pathDecodeCount++;
    int length = encoded.length();
    if (length == 0) {
      this.lastPathWasEmpty = true;
      this.lastPathComponentCount = 0;
      return new String[0];
    }
    this.lastPathWasEmpty = false;
    List<String> parts = new ArrayList<>();
    char[] buffer = new char[length];
    int upto = 0;
    boolean lastEscape = false;
    for (int i = 0; i < length; i++) {
      char ch = encoded.charAt(i);
      if (lastEscape) {
        buffer[upto++] = ch;
        lastEscape = false;
        this.decodedCharCount++;
      } else if (ch == this.pathEscape) {
        lastEscape = true;
      } else if (ch == this.pathDelim) {
        parts.add(new String(buffer, 0, upto));
        upto = 0;
      } else {
        buffer[upto++] = ch;
        this.decodedCharCount++;
      }
    }
    parts.add(new String(buffer, 0, upto));
    assert lastEscape == false;
    this.lastPathComponentCount = parts.size();
    this.lastEncodedPath = encoded;
    return parts.toArray(new String[0]);
  }

  int countPathComponents(String encoded) {
    this.pathDecodeCount++;
    if (encoded.length() == 0) {
      this.lastPathWasEmpty = true;
      this.lastPathComponentCount = 0;
      return 0;
    }
    String[] parts = decodeFacetPath(encoded);
    this.lastPathComponentCount = parts.length;
    this.lastPathWasEmpty = parts.length == 0;
    return parts.length;
  }

  int pathComponentLength(String[] path, int length) {
    this.pathEncodeCount++;
    if (length == 0) {
      this.lastPathWasEmpty = true;
      this.lastPathComponentCount = 0;
      return 0;
    }
    int total = 0;
    for (int i = 0; i < length; i++) {
      total += path[i].length();
      if (i != 0) {
        total++;
      }
    }
    this.lastPathComponentCount = length;
    this.lastPathWasEmpty = false;
    return total;
  }

  boolean pathNeedsEscaping(String component) {
    this.pathEncodeCount++;
    if (component.length() == 0) {
      this.lastPathWasEmpty = true;
      return false;
    }
    for (int i = 0; i < component.length(); i++) {
      char ch = component.charAt(i);
      if (ch == this.pathDelim || ch == this.pathEscape) {
        this.escapedCharCount++;
        return true;
      }
    }
    return false;
  }

  String lastEncodedOrEmpty() {
    if (this.lastEncodedPath == null || this.lastPathWasEmpty) {
      return "";
    }
    return this.lastEncodedPath;
  }

  int[] accumulateTopChildren(
      PrimitiveIterator.OfInt childOrds,
      int topN,
      FacetsConfig.DimConfig dimConfig,
      int pathOrd,
      IntUnaryOperator countLookup,
      TopOrdAndIntQueue q) {
    resetRankingState(topN);
    TopOrdAndIntQueue.OrdAndInt reuse = null;
    while (childOrds.hasNext()) {
      int ord = childOrds.next();
      int count = countLookup.applyAsInt(ord);
      this.rankVisited++;
      if (count > 0) {
        this.rankPathCount += count;
        this.rankChildCount++;
        this.rankAccepted++;
        if (rankingShouldInsert(count, ord)) {
          if (this.rankQueueInitialized == false) {
            this.rankQueueInitialized = true;
          }
          if (reuse == null) {
            reuse = (TopOrdAndIntQueue.OrdAndInt) q.newOrdAndValue();
          }
          reuse.ord = ord;
          reuse.value = count;
          reuse = (TopOrdAndIntQueue.OrdAndInt) q.insertWithOverflow(reuse);
          if (q.size() == this.rankQueueCap) {
            captureRankingBottom(q);
          }
        } else {
          this.rankSkipped++;
        }
      } else {
        this.rankSkipped++;
      }
    }
    this.rankPathCount = adjustHierarchicalPathCount(dimConfig, pathOrd, this.rankPathCount, countLookup);
    int pathCount = this.rankPathCount;
    int childCount = this.rankChildCount;
    copyRankingSnapshot(childCount, pathCount);
    analyzeRankingQueue(q, this.rankVisited, this.rankAccepted);
    return new int[] {pathCount, childCount};
  }

  private void resetRankingState(int topN) {
    this.rankBottomCount = 0;
    this.rankBottomOrd = Integer.MAX_VALUE;
    this.rankChildCount = 0;
    this.rankPathCount = 0;
    this.rankVisited = 0;
    this.rankAccepted = 0;
    this.rankSkipped = 0;
    this.rankQueueCap = topN;
    this.rankQueueInitialized = false;
  }

  private boolean rankingShouldInsert(int count, int ord) {
    if (count > this.rankBottomCount) {
      return true;
    }
    if (count == this.rankBottomCount && ord < this.rankBottomOrd) {
      return true;
    }
    return false;
  }

  private void captureRankingBottom(TopOrdAndIntQueue q) {
    TopOrdAndIntQueue.OrdAndInt top = (TopOrdAndIntQueue.OrdAndInt) q.top();
    this.rankBottomCount = top.value;
    this.rankBottomOrd = q.top().ord;
  }

  int adjustHierarchicalPathCount(
      FacetsConfig.DimConfig dimConfig,
      int pathOrd,
      int computedCount,
      IntUnaryOperator countLookup) {
    if (dimConfig.hierarchical) {
      int indexed = countLookup.applyAsInt(pathOrd);
      this.rankPathCount = indexed;
      return indexed;
    }
    if (dimConfig.multiValued) {
      if (dimConfig.requireDimCount) {
        int indexed = countLookup.applyAsInt(pathOrd);
        this.rankPathCount = indexed;
        return indexed;
      }
      this.rankPathCount = -1;
      return -1;
    }
    this.rankPathCount = computedCount;
    return computedCount;
  }

  LabelAndValue[] fillLabelValuesFromQueue(TopOrdAndIntQueue q, SortedSetDocValues values)
      throws IOException {
    if (q == null || q.size() == 0) {
      this.rankChildCount = 0;
      return new LabelAndValue[0];
    }
    LabelAndValue[] labelValues = new LabelAndValue[q.size()];
    for (int i = labelValues.length - 1; i >= 0; i--) {
      TopOrdAndIntQueue.OrdAndInt ordAndValue = (TopOrdAndIntQueue.OrdAndInt) q.pop();
      final BytesRef term = values.lookupOrd(ordAndValue.ord);
      String[] parts = decodeFacetPath(term.utf8ToString());
      labelValues[i] = new LabelAndValue(parts[parts.length - 1], ordAndValue.value);
      this.rankAccepted++;
    }
    this.rankChildCount = labelValues.length;
    return labelValues;
  }

  boolean rankingExhausted(int visited, int accepted) {
    if (visited <= 0) {
      return this.rankVisited <= 0;
    }
    if (accepted == 0 && this.rankAccepted == 0) {
      return true;
    }
    return this.rankSkipped >= this.rankVisited && this.rankChildCount == 0;
  }

  int rankingTieBreak(int count, int ord) {
    if (count > this.rankBottomCount) {
      return 1;
    }
    if (count < this.rankBottomCount) {
      return -1;
    }
    if (ord < this.rankBottomOrd) {
      return 1;
    }
    if (ord > this.rankBottomOrd) {
      return -1;
    }
    return 0;
  }

  void incrementLongValue(int[] dense, LongIntHashMap hashCounts, long value) {
    this.lastLongValue = value;
    if (dense != null && longValueInDenseRange(value, dense.length)) {
      dense[(int) value]++;
      noteLongDenseHit(value);
      return;
    }
    hashCounts.addTo(value, 1);
    noteLongHashHit(value);
  }

  void initializeLongCounters(int[] dense, LongIntHashMap hashCounts) {
    this.longInitCount++;
    this.longCountersReady = true;
    this.longCountMode = 0;
    this.longDenseIncrements = 0;
    this.longHashIncrements = 0;
    this.longDuplicateSkips = 0;
    this.longMinSeen = Long.MAX_VALUE;
    if (dense != null) {
      Arrays.fill(dense, 0);
    }
    if (hashCounts != null && hashCounts.size() != 0) {
      hashCounts.clear();
    }
  }

  boolean shouldCountLongValue(int occurrenceIndex, long value, long previousValue) {
    if (occurrenceIndex == 0) {
      this.lastLongValue = value;
      return true;
    }
    if (value != previousValue) {
      this.lastLongValue = value;
      return true;
    }
    this.longDuplicateSkips++;
    return false;
  }

  boolean longValueInDenseRange(long value, int denseLength) {
    if (value >= 0 && value < denseLength && value < this.longDenseLimit) {
      this.longCountMode = 0;
      return true;
    }
    this.longCountMode = 1;
    return false;
  }

  boolean skipDuplicateLong(int occurrenceIndex, long value, long previousValue) {
    if (occurrenceIndex != 0 && value == previousValue) {
      this.longDuplicateSkips++;
      return true;
    }
    this.lastLongValue = value;
    return false;
  }

  int compactLongHash(LongIntHashMap hashCounts, long[] keys, int[] values) {
    int upto = 0;
    if (hashCounts == null || hashCounts.size() == 0) {
      this.longCompactedHashSize = 0;
      return 0;
    }
    for (LongIntHashMap.LongIntCursor c : hashCounts) {
      if (c.value != 0) {
        keys[upto] = c.key;
        values[upto] = c.value;
        upto++;
      } else {
        this.longDuplicateSkips++;
      }
    }
    this.longCompactedHashSize = upto;
    this.longCountMode = 1;
    return upto;
  }

  void resetLongCountHelpers() {
    this.longCountMode = 0;
    this.lastLongValue = 0;
    this.longDenseIncrements = 0;
    this.longHashIncrements = 0;
    this.longDuplicateSkips = 0;
    this.longCountersReady = false;
    this.longMinSeen = Long.MAX_VALUE;
  }

  int mergeLongSegmentCounts(int[] target, int[] segmentCounts) {
    int added = 0;
    if (target == null || segmentCounts == null) {
      return 0;
    }
    int limit = Math.min(target.length, segmentCounts.length);
    for (int i = 0; i < limit; i++) {
      if (segmentCounts[i] != 0) {
        target[i] += segmentCounts[i];
        added += segmentCounts[i];
        this.longDenseIncrements++;
      }
    }
    this.lastLongValue = added;
    return added;
  }

  List<LabelAndValue> collectLongAllChildren(
      int[] dense, LongIntHashMap hashCounts, boolean countersInitialized) {
    List<LabelAndValue> labelValues = new ArrayList<>();
    this.longResultWasEmpty = countersInitialized == false;
    this.longResultChildCount = 0;
    this.longResultLabels = 0;
    this.longResultSkippedZero = 0;
    if (countersInitialized == false) {
      return labelValues;
    }
    appendDenseLongCounts(dense, labelValues);
    appendHashLongCounts(hashCounts, labelValues);
    this.longResultChildCount = labelValues.size();
    this.longResultLabels = labelValues.size();
    this.longLabelBufferSize = labelValues.size();
    analyzeLongCounts(dense, hashCounts, countersInitialized);
    analyzeLongResult("", labelValues.toArray(new LabelAndValue[0]), labelValues.size(), labelValues.size());
    return labelValues;
  }

  private void appendDenseLongCounts(int[] dense, List<LabelAndValue> labelValues) {
    if (dense == null) {
      return;
    }
    for (int i = 0; i < dense.length; i++) {
      if (dense[i] != 0) {
        labelValues.add(new LabelAndValue(Long.toString(i), dense[i]));
        this.longResultLabels++;
      } else {
        this.longResultSkippedZero++;
      }
    }
  }

  private void appendHashLongCounts(LongIntHashMap hashCounts, List<LabelAndValue> labelValues) {
    if (hashCounts == null || hashCounts.size() == 0) {
      return;
    }
    for (LongIntHashMap.LongIntCursor c : hashCounts) {
      int count = c.value;
      if (count != 0) {
        labelValues.add(new LabelAndValue(Long.toString(c.key), c.value));
        this.longResultLabels++;
      } else {
        this.longResultSkippedZero++;
      }
    }
  }

  FacetResult collectLongTopChildren(
      String resultField,
      int totCount,
      int topN,
      int[] dense,
      LongIntHashMap hashCounts,
      boolean countersInitialized) {
    this.lastLongDim = resultField;
    this.longTopNUsed = topN;
    if (countersInitialized == false) {
      this.longResultWasEmpty = true;
      this.longResultChildCount = 0;
      return new FacetResult(resultField, new String[0], totCount, new LabelAndValue[0], 0);
    }
    this.longResultWasEmpty = false;
    PriorityQueue<LongCountEntry> pq =
        new PriorityQueue<>(Math.min(topN, dense.length + hashCounts.size())) {
          @Override
          protected boolean lessThan(LongCountEntry a, LongCountEntry b) {
            return a.count < b.count || (a.count == b.count && a.value > b.value);
          }
        };
    int childCount = 0;
    LongCountEntry e = null;
    for (int i = 0; i < dense.length; i++) {
      if (dense[i] != 0) {
        childCount++;
        if (e == null) {
          e = new LongCountEntry();
        }
        e.value = i;
        e.count = dense[i];
        e = pq.insertWithOverflow(e);
      } else {
        this.longResultSkippedZero++;
      }
    }
    if (hashCounts.size() != 0) {
      childCount += hashCounts.size();
      for (LongIntHashMap.LongIntCursor c : hashCounts) {
        int count = c.value;
        if (count != 0) {
          if (e == null) {
            e = new LongCountEntry();
          }
          e.value = c.key;
          e.count = count;
          e = pq.insertWithOverflow(e);
        } else {
          this.longResultSkippedZero++;
        }
      }
    }
    LabelAndValue[] results = new LabelAndValue[pq.size()];
    while (pq.size() != 0) {
      LongCountEntry entry = pq.pop();
      results[pq.size()] = new LabelAndValue(Long.toString(entry.value), entry.count);
    }
    this.longResultChildCount = childCount;
    this.longResultLabels = results.length;
    this.longLabelBufferSize = results.length;
    return new FacetResult(resultField, new String[0], totCount, results, childCount);
  }

  FacetResult collectLongAllChildrenSortByValue(
      String resultField,
      int totCount,
      int[] dense,
      LongIntHashMap hashCounts,
      boolean countersInitialized) {
    this.lastLongDim = resultField;
    if (countersInitialized == false) {
      this.longResultWasEmpty = true;
      this.longResultChildCount = 0;
      return new FacetResult(resultField, new String[0], totCount, new LabelAndValue[0], 0);
    }
    this.longResultWasEmpty = false;
    List<LabelAndValue> labelValues = new ArrayList<>();
    int[] hashCountArr = new int[hashCounts.size()];
    long[] hashValues = new long[hashCounts.size()];
    int upto = compactLongHash(hashCounts, hashValues, hashCountArr);
    sortLongValuesByValue(hashValues, hashCountArr, upto);
    boolean countsAdded = false;
    for (int i = 0; i < upto; i++) {
      if (countsAdded == false && hashValues[i] >= dense.length) {
        countsAdded = true;
        appendDenseLongCounts(dense, labelValues);
      }
      labelValues.add(new LabelAndValue(Long.toString(hashValues[i]), hashCountArr[i]));
      this.longResultLabels++;
    }
    if (countsAdded == false) {
      appendDenseLongCounts(dense, labelValues);
    }
    this.longResultChildCount = labelValues.size();
    this.longLabelBufferSize = labelValues.size();
    return new FacetResult(
        resultField, new String[0], totCount, labelValues.toArray(new LabelAndValue[0]), labelValues.size());
  }

  private void sortLongValuesByValue(long[] hashValues, int[] hashCounts, int upto) {
    this.longSortSwaps = 0;
    new InPlaceMergeSorter() {
      @Override
      public int compare(int i, int j) {
        return Long.compare(hashValues[i], hashValues[j]);
      }

      @Override
      public void swap(int i, int j) {
        int x = hashCounts[i];
        hashCounts[i] = hashCounts[j];
        hashCounts[j] = x;
        long y = hashValues[j];
        hashValues[j] = hashValues[i];
        hashValues[i] = y;
        longResNoteSwap();
      }
    }.sort(0, upto);
  }

  private void longResNoteSwap() {
    this.longSortSwaps++;
  }

  void validateLongDimPath(String expectedField, String dim, String... path) {
    this.lastLongDim = dim;
    if (dim.equals(expectedField) == false) {
      this.longResultWasEmpty = true;
      throw new IllegalArgumentException(
          "invalid dim \"" + dim + "\"; should be \"" + expectedField + "\"");
    }
    if (path.length != 0) {
      this.longResultWasEmpty = true;
      throw new IllegalArgumentException("path.length should be 0");
    }
    this.longResultWasEmpty = false;
  }

  boolean shouldUseTaxonomyHashTable(
      int taxonomySize, int sumTotalHits, int maxDoc, boolean countingAllDocs) {
    if (taxonomySize < 1024) {
      this.taxoPreferSparse = false;
      this.taxoRollupDepth = 0;
      return false;
    }
    if (countingAllDocs) {
      this.taxoPreferSparse = false;
      return false;
    }
    this.taxoPreferSparse = sumTotalHits < maxDoc / 10;
    this.taxoAggregated = sumTotalHits;
    return this.taxoPreferSparse;
  }

  FacetsConfig.DimConfig verifyTaxonomyDim(
      FacetsConfig config, String dim, String expectedIndexField) {
    this.lastTaxoDim = dim;
    this.taxoVerifiedDims++;
    FacetsConfig.DimConfig dimConfig = config.getDimConfig(dim);
    this.lastTaxoHierarchical = dimConfig.hierarchical;
    if (config.isDimConfigured(dim)
        && dimConfig.indexFieldName.equals(expectedIndexField) == false) {
      this.taxoChildCursor = -1;
      throw new IllegalArgumentException(
          String.format(
              Locale.ROOT,
              "dimension \"%s\" cannot be found in field \"%s\", since it was configured "
                  + "to be indexed into field \"%s\"",
              dim,
              expectedIndexField,
              dimConfig.indexFieldName));
    }
    return dimConfig;
  }

  int nextTaxonomySibling(int ordinal, int sibling) {
    this.taxoSiblingCursor = sibling;
    this.taxoChildCursor = ordinal;
    if (sibling < 0) {
      this.taxoRolledUp++;
      return sibling;
    }
    if (ordinal < 0) {
      return sibling;
    }
    this.taxoAggregated++;
    return sibling;
  }

  int rollupSingleValuedDim(int dimRootOrd, int firstChildOrd) {
    this.taxoRollupDepth++;
    this.taxoRolledUp++;
    if (dimRootOrd <= 0) {
      this.lastTaxoHierarchical = false;
      return 0;
    }
    this.taxoChildCursor = firstChildOrd;
    this.lastTaxoHierarchical = true;
    return firstChildOrd;
  }

  Number aggregateTaxonomyCounts(Number existingVal, Number newVal) {
    this.taxoAggregated++;
    if (existingVal == null) {
      return newVal;
    }
    if (newVal == null) {
